    constant = json.loads(cons)

    dt = datetime.datetime.fromtimestamp(timestamp,tz=tz)
    year = dt.year
    month = dt.month

    day = dt.day + dt.hour / 24.0  + dt.minute / 60.0 / 24.0 + dt.second / 3600.0 / 24.0

    mjd = Epoch(year,month,day).jde()

    # print(mjd)

