    astrodict = {}

    try:
        s = sun(city.observer, date = dt_noon, tzinfo=location.timezone)
        astrodict["richu"] = s["sunrise"].timestamp()
        astrodict["riluo"] = s["sunset"].timestamp()
        astrodict["shimingshuguang"] = s["dawn"].timestamp()
        astrodict["shimingmuguang"] = s["dusk"].timestamp()
    except Exception as e:
        pass
