def preidcttideone(const, mjd, fu,correct):

    timestep = (mjd - startjd) * 86400


    cn = len(fullConstIndex)

    pf = fu[0]

    pu = fu[1]


    h = 0.0
    for j in range(0,cn):
        cIndex = fullConstIndex[j]


        himI = const[2 * j]
        hreI = const[2 * j+1]

        him  = himI

        hre = hreI

        xita = OMEGA_d[cIndex] * timestep + PHASE_mkB[cIndex] + pu[j]
        h += pf[j] * hre * math.cos(xita) - pf[j] * him * math.sin(xita)

    if correct:
        dh = infer_minor(const,mjd)
        h += dh
    return h / 1000.0



